# Generated by AI

from fastapi import APIRouter, Request
from fastapi.responses import JSONResponse

from app.api.dependencies import DisplayLanguage, ServiceDependency
from app.core.language import localized
from app.schemas.ai import ChatRequest, ChatResponse
from app.services.gemini_agent import chat

router = APIRouter(prefix="/ai", tags=["AgroSat IA"])


@router.post(
    "/chat", summary="Conversar com o assistente AgroSat IA",
    responses={429: {"model": ChatResponse, "description": "Limite local de requisições."}},
)
async def chat_route(
    request: Request, body: ChatRequest, services: ServiceDependency, language: DisplayLanguage,
) -> ChatResponse:
    state = request.app.state
    location = state.boundaries.locate(body.location) if body.location is not None else None
    host = request.client.host if request.client else "unknown"
    if state.gemini is not None and not state.chat_limit.allow(host):
        response = ChatResponse(
            status="rate_limited",
            answer=localized(
                language, "Limite de consultas do assistente atingido. Tente em um minuto.",
                "The assistant has reached its request limit. Try again in a minute.",
            ),
            location=location,
        )
        return JSONResponse(
            status_code=429, content=response.model_dump(mode="json"),
            headers={"Retry-After": "60", "Content-Language": language, "Vary": "Accept-Language"},
        )
    return await chat(state.gemini, services.client, services.settings, state.zarc, location, body, language)
